#include "profiles/whj2.hpp"
#include "qlie.hpp"
#include <filesystem>
#include <iostream>
namespace fs=std::filesystem;
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("usage: qlie-unpack GAME OUTPUT");std::string game=argv[1];fs::path out=argv[2];auto keys=qlie::game_keys(game,whj2::profile::archives);size_t total=0;uint64_t bytes=0;for(int i:{0,2,3,6,7,8}){std::string base="data"+std::to_string(i);qlie::Pack p(game+"/GameData/"+base+".pack",keys.first,keys.second);size_t count=0;uint64_t packbytes=0;for(const auto&e:p.entries){std::string relative=e.name;for(auto&c:relative)if(c==92)c=47;fs::path path(relative);if(path.is_absolute())throw std::runtime_error("Absolute archive path");for(const auto&part:path)if(part=="..")throw std::runtime_error("Parent archive path");auto b=p.read(e);fs::path dest=out/base/path;fs::create_directories(dest.parent_path());if(fs::exists(dest)){if(qlie::file(dest.string())!=b)throw std::runtime_error("Existing output differs: "+dest.string());}else{auto temp=dest;temp+=".part";qlie::write_file(temp.string(),b);fs::rename(temp,dest);}count++;packbytes+=b.size();if(count%200==0)std::cout<<base<<" "<<count<<" files\n";}std::cout<<"PASS "<<base<<" files="<<count<<" bytes="<<packbytes<<"\n";total+=count;bytes+=packbytes;}std::cout<<"COMPLETE files="<<total<<" bytes="<<bytes<<" output="<<fs::absolute(out).string()<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
